<?php
declare(strict_types=1);function x1_env_load():array{static $env=null;if($env!==null)return $env;$env=[];$path=X1_ROOT.'/.env';if(!is_file($path))return $env;foreach(file($path,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[]as $line){$line=trim($line);if($line===''||str_starts_with($line,'#')||!str_contains($line,'='))continue;[$k,$v]=array_map('trim',explode('=',$line,2));if(($v[0]??'')==='"'&&str_ends_with($v,'"'))$v=stripcslashes(substr($v,1,-1));$env[$k]=$v;}return $env;}function x1_env(string $key,?string $default=null):?string{$e=x1_env_load();$v=$e[$key]??getenv($key);return($v===false||$v===null||$v==='')?$default:(string)$v;}function x1_db_supported():bool{return class_exists('PDO')&&in_array('sqlite',PDO::getAvailableDrivers(),true);}function x1_db_path():string{return x1_env('X1_DB_PATH',X1_ROOT.'/storage/x1-waveo.sqlite');}function x1_db():?PDO{static $db=false;if($db instanceof PDO)return $db;if($db===null)return null;if(!x1_db_supported()){$db=null;return null;}$path=x1_db_path();if(!is_dir(dirname($path)))@mkdir(dirname($path),0770,true);try{$pdo=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false,]);$pdo->exec('PRAGMA journal_mode=WAL');$pdo->exec('PRAGMA foreign_keys=ON');$pdo->exec('PRAGMA busy_timeout=5000');x1_db_migrate($pdo);$db=$pdo;return $db;}catch(Throwable $e){error_log('X1 DB init failed: '.$e->getMessage());$db=null;return null;}}function x1_db_migrate(PDO $db):void{$db->exec('CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)');$done=array_map('intval',$db->query('SELECT version FROM schema_migrations')->fetchAll(PDO::FETCH_COLUMN));foreach(glob(X1_ROOT.'/migrations/*.sql')?:[]as $file){if(!preg_match('/\/(\d+)_/',str_replace('\\','/',$file),$m))continue;$version=(int)$m[1];if(in_array($version,$done,true))continue;$sql=(string)file_get_contents($file);$db->beginTransaction();try{$db->exec($sql);$st=$db->prepare('INSERT INTO schema_migrations(version,applied_at) VALUES(?,?)');$st->execute([$version,date('c')]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}}function x1_db_scalar(string $sql,array $params=[],$default=null){$db=x1_db();if(!$db)return $default;$st=$db->prepare($sql);$st->execute($params);$v=$st->fetchColumn();return $v===false?$default:$v;}function x1_db_all(string $sql,array $params=[]):array{$db=x1_db();if(!$db)return[];$st=$db->prepare($sql);$st->execute($params);return $st->fetchAll()?:[];}function x1_db_one(string $sql,array $params=[]):?array{$rows=x1_db_all($sql,$params);return $rows[0]??null;}function x1_db_exec(string $sql,array $params=[]):bool{$db=x1_db();if(!$db)return false;$st=$db->prepare($sql);return $st->execute($params);}